use std::collections::HashMap;
use std::path::{Path, PathBuf};

pub fn panic_at(location: &str, message: &str) -> ! {
    let pid = std::process::id();
    eprintln!();
    eprintln!("thread 'main' ({}) panicked at {}:", pid, location);
    eprintln!("{}", message);
    eprintln!("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace");
    std::process::exit(101);
}

pub fn panic_option(location: &str) -> ! {
    panic_at(location, "called `Option::unwrap()` on a `None` value");
}

pub fn panic_tryfrom(location: &str) -> ! {
    panic_at(location, "called `Result::unwrap()` on an `Err` value: TryFromIntError(())");
}

pub fn panic_os(location: &str, err: std::io::Error) -> ! {
    panic_at(location, &format!("called `Result::unwrap()` on an `Err` value: {:?}", err));
}

pub fn panic_failed_read(path_display: &str) -> ! {
    panic_at("src/config.rs:119:9", &format!("Failed to read config file at {}", path_display));
}

#[derive(Debug, Clone)]
pub struct RawConfig {
    pub map: HashMap<String, toml::Value>,
}

pub fn find_config_path(cli_config: Option<&String>, noconfig: bool) -> Option<String> {
    if noconfig {
        if let Some(p) = cli_config {
            return Some(p.clone());
        } else {
            return None;
        }
    }
    if let Some(p) = cli_config {
        return Some(p.clone());
    }
    // cwd
    if let Ok(cwd) = std::env::current_dir() {
        let p = cwd.join("tex-fmt.toml");
        if p.is_file() {
            return Some(p.to_string_lossy().to_string());
        }
    }
    // git root
    if let Some(git_root) = find_git_root() {
        let p = Path::new(&git_root).join("tex-fmt.toml");
        if p.is_file() {
            return Some(p.to_string_lossy().to_string());
        }
    }
    // user config
    if let Some(mut cfg_dir) = dirs::config_dir() {
        cfg_dir.push("tex-fmt");
        cfg_dir.push("tex-fmt.toml");
        if cfg_dir.is_file() {
            return Some(cfg_dir.to_string_lossy().to_string());
        }
    }
    None
}

fn find_git_root() -> Option<String> {
    // Try git rev-parse
    if let Ok(output) = std::process::Command::new("git")
        .arg("rev-parse")
        .arg("--show-toplevel")
        .output()
    {
        if output.status.success() {
            let s = String::from_utf8_lossy(&output.stdout).trim().to_string();
            if !s.is_empty() {
                return Some(s);
            }
        }
    }
    None
}

pub fn load_raw_config(path_display: Option<&String>, noconfig: bool, cli_config: Option<&String>) -> (Option<String>, HashMap<String, toml::Value>) {
    // Returns (display_path, map)
    if noconfig {
        let disp = cli_config.cloned();
        return (disp, HashMap::new());
    }
    if let Some(p) = cli_config {
        // explicit config: must read, panic on open error at 83:63
        let content = match std::fs::read_to_string(p) {
            Ok(c) => c,
            Err(e) => panic_os("src/config.rs:83:63", e),
        };
        // parse TOML, panic at 119:9 on failure
        let parsed: Result<toml::Value, _> = toml::from_str(&content);
        match parsed {
            Ok(toml::Value::Table(map)) => {
                let hm: HashMap<String, toml::Value> = map.into_iter().collect();
                return (Some(p.clone()), hm);
            }
            _ => {
                panic_failed_read(p);
            }
        }
    }
    // discovered
    let found = find_config_path(None, false);
    if let Some(path) = found {
        // Try to read; if fails? For discovered, what happens? Assume panic at 119:9? Or ignore?
        // Let's try to read, if fails, treat as no config? But to match original, need to test.
        // For now, if read fails, return None with empty (ignore).
        // Actually, for discovered, file exists (is_file checked), so read should succeed except permissions.
        // Let's attempt read, if fails, panic at 119:9? We'll do that.
        let content = match std::fs::read_to_string(&path) {
            Ok(c) => c,
            Err(_) => panic_failed_read(&path),
        };
        let parsed: Result<toml::Value, _> = toml::from_str(&content);
        match parsed {
            Ok(toml::Value::Table(map)) => {
                let hm: HashMap<String, toml::Value> = map.into_iter().collect();
                return (Some(path), hm);
            }
            _ => {
                panic_failed_read(&path);
            }
        }
    }
    (None, HashMap::new())
}

pub fn get_bool(map: &HashMap<String, toml::Value>, key: &str, location: &str) -> Option<bool> {
    if let Some(v) = map.get(key) {
        match v {
