    if let Some(v) = map.get(key) {
        match v {
            toml::Value::Integer(i) => {
                // try_into usize
                let u: Result<usize, _> = (*i).try_into();
                match u {
                    Ok(val) => Some(val),
                    Err(_) => panic_tryfrom(loc_try),
                }
            }
            _ => panic_option(loc_none),
        }
    } else {
        None
    }
}

