pub fn get_string_array(map: &HashMap<String, toml::Value>, key: &str) -> Option<Vec<String>> {
    if let Some(v) = map.get(key) {
        match v {
            toml::Value::Array(arr) => {
                let mut out = Vec::new();
                for item in arr {
                    if let toml::Value::String(s) = item {
                        out.push(s.clone());
                    }
                }
                Some(out)
            }
            _ => {
                // Wrong type: ignore (return None to use defaults)? Original ignores (no panic, uses defaults).
                // For lists = "a" (string), it ignored and used defaults. Good.
                // So return None (meaning no custom, use defaults).
                // But what about empty array vs missing? Both give defaults? For wrap-chars, empty array would give empty (same as defaults empty). Good.
                // For lists with wrong type, return None (defaults).
                None
            }
        }
    } else {
        None
    }
}
