use std::collections::HashMap;
use crate::config;

#[derive(Debug, Clone)]
pub struct Settings {
    pub check: bool,
    pub print: bool, // display print (includes stdin)
    pub print_flag: bool, // actual print flag (CLI or config, without stdin?) For behavior, print mode is (print_flag || stdin?) Actually stdin mode is separate. Let's store actual flags.
    pub fail_display: bool, // buggy display: print || stdin
    pub fail_actual: bool, // CLI fail || config fail
    pub wrap: bool,
    pub wraplen: usize,
    pub wrapmin: usize,
    pub tabsize: u8,
    pub tabchar: String, // "space" or "tab"
    pub stdin: bool,
    pub verbosity: String, // "error","warn","info","trace"
    pub verbosity_num: u8, // 0,1,2,3
    pub lists: Vec<String>,
    pub verbatims: Vec<String>,
    pub no_indent_envs: Vec<String>,
    pub wrap_chars: Vec<String>,
    pub config_display: Option<String>,
}

pub fn build_settings(
    matches: &clap::ArgMatches,
    raw_map: &HashMap<String, toml::Value>,
    config_display: Option<String>,
