use crate::settings::Settings;
use crate::config;

fn is_ascii_letter(c: char) -> bool { c.is_ascii_alphabetic() }

fn find_comment_start(s: &str) -> Option<usize> {
    let chars: Vec<(usize, char)> = s.char_indices().collect();
    for i in 0..chars.len() {
        let (bi, c) = chars[i];
        if c == '%' {
            if i == 0 { return Some(bi); }
            let (_, prev) = chars[i-1];
            if prev != '\\' { return Some(bi); }
        }
    }
    None
}
fn has_verb_prot(code: &str) -> bool { code.contains("\\verb|") || code.contains("\\verb+") }
fn has_mint(code: &str) -> bool { code.contains("\\mintinline") }
fn starts_with_item(code: &str) -> bool {
    if code.starts_with("\\item") {
        let rest = &code[5..];
        if rest.is_empty() { return true; }
        let f = rest.chars().next().unwrap();
        if !is_ascii_letter(f) { return true; }
    }
    false
}
fn find_splits(code: &str) -> Vec<usize> {
    let mut v = Vec::new();
    let len = code.len();
    let mut i = 0;
    while i < len {
        if i+7 <= len && &code[i..i+7]=="\\begin{" { if i!=0 { v.push(i); } i+=7; continue; }
        if i+5 <= len && &code[i..i+5]=="\\end{" { if i!=0 { v.push(i); } i+=5; continue; }
        if i+5 <= len && &code[i..i+5]=="\\item" {
            let after = i+5;
            let b = if after>=len { true } else { let c=code[after..].chars().next().unwrap(); !is_ascii_letter(c) };
            if b && i!=0 { v.push(i); }
            i+=5; continue;
        }
        let cl = code[i..].chars().next().unwrap().len_utf8();
        i+=cl;
    }
    v
}
fn extract_env(s: &str) -> Option<String> {
    if let Some(o) = s.find('{') {
        if let Some(c) = s[o+1..].find('}') {
            return Some(s[o+1..o+1+c].to_string());
        }
    }
    None
}
fn count_verb(line: &str, verbs: &[String]) -> (i32,i32) {
    let mut b=0; let mut e=0;
    for v in verbs {
        let bp = format!("\\begin{{{}}}", v);
        let ep = format!("\\end{{{}}}", v);
        b += line.matches(&bp).count() as i32;
        e += line.matches(&ep).count() as i32;
    }
    (b,e)
}
fn rtrim_st(s: &str) -> &str { s.trim_end_matches(|c| c==' '||c=='\t') }
fn expand_tabs(s: &str, ts: u8) -> String {
    if !s.contains('\t') { return s.to_string(); }
    s.replace('\t', &" ".repeat(ts as usize))
}
fn calc_indent(code: &str, prev: i32, settings: &Settings, prot: bool) -> (i32,i32) {
    let mut ev: Vec<(usize,i32)> = Vec::new();
    let mut item_d = false;
    if !prot {
        if starts_with_item(code) && prev>0 { item_d=true; }
        let L=code.len(); let mut i=0;
        while i<L {
            if i+7<=L && &code[i..i+7]=="\\begin{" {
                let rest=&code[i..];
                let env=extract_env(rest);
                let d=if let Some(e)=env { if settings.lists.contains(&e){2} else if settings.no_indent_envs.contains(&e){0} else {1} } else {1};
                ev.push((i,d)); i+=7; continue;
            }
            if i+5<=L && &code[i..i+5]=="\\end{" {
                let rest=&code[i..];
                let env=extract_env(rest);
                let d=if let Some(e)=env { if settings.lists.contains(&e){-2} else if settings.no_indent_envs.contains(&e){0} else {-1} } else {-1};
                ev.push((i,d)); i+=5; continue;
            }
            let cl=code[i..].chars().next().unwrap().len_utf8(); i+=cl;
        }
    }
    let mut bev: Vec<(usize,i32)> = Vec::new();
    for (bi,c) in code.char_indices() {
        match c { '{'| '[' | '(' => bev.push((bi,1)), '}'|']'|')' => bev.push((bi,-1)), _=>{} }
    }
    let mut all=ev; all.extend(bev); all.sort_by_key(|(p,_)|*p);
    let mut d=prev; let mut m=prev;
    for (_,dd) in &all { d+=*dd; if d<m {m=d;} }
    let fin=d;
    let vis=if item_d { m-1 } else { m };
    (fin,vis)
}

