use crate::settings::Settings;
use crate::config;

fn is_ascii_letter(c: char) -> bool { c.is_ascii_alphabetic() }
fn find_comment_start(s: &str) -> Option<usize> {
    let v: Vec<(usize,char)> = s.char_indices().collect();
    for i in 0..v.len() {
        let (bi,c)=v[i];
        if c=='%' {
            if i==0 { return Some(bi); }
            if v[i-1].1!='\\' { return Some(bi); }
        }
    }
    None
}
fn has_verb(code: &str) -> bool { code.contains("\\verb|")||code.contains("\\verb+") }
fn has_mint(code: &str) -> bool { code.contains("\\mintinline") }
fn starts_item(code: &str) -> bool {
    if code.starts_with("\\item") {
        let r=&code[5..];
        if r.is_empty() { return true; }
        if !is_ascii_letter(r.chars().next().unwrap()) { return true; }
