}
fn find_splits(code: &str) -> Vec<usize> {
    let mut v=Vec::new();
    let L=code.len(); let mut i=0;
    while i<L {
        if i+7<=L && &code[i..i+7]=="\\begin{" { if i!=0{v.push(i);} i+=7; continue; }
        if i+5<=L && &code[i..i+5]=="\\end{" { if i!=0{v.push(i);} i+=5; continue; }
