cat > src/format.rs <<'RS'
use crate::settings::Settings;
use crate::config;

fn is_ascii_letter(c: char) -> bool { c.is_ascii_alphabetic() }
fn find_comment_start(s: &str) -> Option<usize> {
    let v: Vec<(usize,char)> = s.char_indices().collect();
    for i in 0..v.len() {
        let (bi,c)=v[i];
        if c=='%' {
            if i==0 { return Some(bi); }
            if v[i-1].1!='\\' { return Some(bi); }
        }
    }
    None
}
fn has_verb(code: &str) -> bool { code.contains("\\verb|")||code.contains("\\verb+") }
fn has_mint(code: &str) -> bool { code.contains("\\mintinline") }
fn starts_item(code: &str) -> bool {
    if code.starts_with("\\item") {
        let r=&code[5..];
        if r.is_empty() { return true; }
        if !is_ascii_letter(r.chars().next().unwrap()) { return true; }
    }
    false
}
fn find_splits(code: &str) -> Vec<usize> {
    let mut v=Vec::new();
    let L=code.len(); let mut i=0;
    while i<L {
        if i+7<=L && &code[i..i+7]=="\\begin{" { if i!=0{v.push(i);} i+=7; continue; }
        if i+5<=L && &code[i..i+5]=="\\end{" { if i!=0{v.push(i);} i+=5; continue; }
        if i+5<=L && &code[i..i+5]=="\\item" {
            let a=i+5;
            let b=if a>=L{true}else{!is_ascii_letter(code[a..].chars().next().unwrap())};
            if b&&i!=0{v.push(i);} i+=5; continue;
        }
        i+=code[i..].chars().next().unwrap().len_utf8();
    }
    v
}
fn extract_env(s: &str) -> Option<String> {
    if let Some(o)=s.find('{') { if let Some(c)=s[o+1..].find('}') { return Some(s[o+1..o+1+c].to_string()); } }
    None
}
fn count_verb(line: &str, verbs: &[String]) -> (i32,i32) {
    let mut b=0; let mut e=0;
    for v in verbs {
        let bp=format!("\\begin{{{}}}",v);
        let ep=format!("\\end{{{}}}",v);
        b+=line.matches(&bp).count() as i32;
        e+=line.matches(&ep).count() as i32;
    }
    (b,e)
}
fn rtrim_st(s: &str) -> &str { s.trim_end_matches(|c| c==' '||c=='\t') }
fn expand_tabs(s: &str, ts: u8) -> String { if !s.contains('\t'){return s.to_string();} s.replace('\t',&" ".repeat(ts as usize)) }
